startup_command:
python -c import os,socket,socketserver,threading
upstream=(os.environ["IDENTITY_UPSTREAM_IP"],443)
def pump(a,b):
    try:
        while data:=a.recv(65536): b.sendall(data)
    except OSError: pass
    finally:
        try: b.shutdown(socket.SHUT_WR)
        except OSError: pass
class Handler(socketserver.BaseRequestHandler):
    def handle(self):
        peer=socket.create_connection(upstream,5)
        thread=threading.Thread(target=pump,args=(self.request,peer),daemon=True)
        thread.start(); pump(peer,self.request); thread.join()
class Server(socketserver.ThreadingTCPServer):
    allow_reuse_address=True
    daemon_threads=True
Server(("0.0.0.0",443),Handler).serve_forever()
